// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VoiceAudioRun) predicate.VoiceAudioRun {
	return predicate.VoiceAudioRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VoiceAudioRun) predicate.VoiceAudioRun {
	return predicate.VoiceAudioRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VoiceAudioRun) predicate.VoiceAudioRun {
	return predicate.VoiceAudioRun(sql.NotPredicates(p))
}





